const homeFilmPosters={"desktop":"data:image/webp;base64,","mobile":"data:image/webp;base64,"};
/* Silent marketing film: no customer data, music, or third-party video embed. */
let heroVideoDisposer=null;
function cleanupHeroVideo(){cleanupHeadlineVideo();if(heroVideoDisposer){heroVideoDisposer();heroVideoDisposer=null;}}
function initHeroVideo(){
 cleanupHeroVideo();const figure=document.querySelector('.merchant-hero'),frame=figure?.querySelector('.merchant-photo-frame');if(!frame)return;
 const controller=new AbortController(),signal=controller.signal;let disposed=false,observer=null,visible=false,loaded=false,loadRequested=false;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),mobile=matchMedia('(max-width: 600px)'),saveData=Boolean(navigator.connection?.saveData);
 let wantsPlay=!reduced.matches&&!saveData;
 const on=(el,event,fn,opts={})=>el.addEventListener(event,fn,{...opts,signal});
 figure.classList.add('has-film');
 const video=document.createElement('video');video.id='home-brand-film';video.className='home-brand-film';video.muted=true;video.defaultMuted=true;video.loop=true;video.playsInline=true;video.preload='none';video.disableRemotePlayback=true;video.disablePictureInPicture=true;video.setAttribute('controlslist','nodownload noremoteplayback');video.setAttribute('muted','');video.setAttribute('playsinline','');video.setAttribute('aria-label','Présentation animée de Boutilo, vingt secondes, sans son');video.setAttribute('aria-describedby','home-film-transcript');video.poster=homeFilmPosters[mobile.matches?'mobile':'desktop'];const fallback=frame.querySelector('img');if(fallback)fallback.src=video.poster;frame.append(video);
 const controls=document.createElement('div');controls.className='home-film-controls';controls.innerHTML=`<button class="home-film-toggle" type="button" aria-controls="home-brand-film" aria-label="Lire la vidéo de présentation"><span class="film-control-symbol" aria-hidden="true">▶</span><span class="film-control-label">Lire</span></button><span class="home-film-time" aria-hidden="true">00:00 / 00:20</span><label class="home-film-seek-label"><span class="home-film-sr">Position dans la vidéo de présentation</span><input class="home-film-seek" type="range" min="0" max="20" step="0.1" value="0" disabled></label><span class="home-film-silent">Sans son</span>`;
 const caption=figure.querySelector('figcaption');caption.before(controls);caption.classList.add('home-film-caption');caption.textContent='Film animé · 20 secondes · Visuels générés par IA';
 const transcript=document.createElement('p');transcript.id='home-film-transcript';transcript.className='home-film-sr';transcript.textContent='Boutilo aide les alimentations générales et les magasins d’électroménager à suivre leurs ventes, leurs stocks et les crédits clients. Chaque commerçant dispose de son propre espace. Présentation réalisée à partir d’illustrations générées par IA, avec mouvements de cadrage et transitions, sans son.';figure.append(transcript);
 const toggle=controls.querySelector('button'),symbol=controls.querySelector('.film-control-symbol'),label=controls.querySelector('.film-control-label'),seek=controls.querySelector('input'),time=controls.querySelector('.home-film-time');
 const format=n=>'00:'+String(Math.floor(Math.max(0,n||0))).padStart(2,'0');
 function update(){if(disposed)return;const playing=!video.paused&&!video.ended;symbol.textContent=playing?'Ⅱ':'▶';label.textContent=playing?'Pause':'Lire';toggle.setAttribute('aria-label',playing?'Mettre la vidéo de présentation en pause':'Lire la vidéo de présentation');toggle.setAttribute('aria-pressed',String(playing));const duration=Number.isFinite(video.duration)&&video.duration>0?video.duration:20;time.textContent=format(video.currentTime)+' / '+format(duration);seek.max=String(duration);seek.value=String(video.currentTime||0);seek.style.setProperty('--played',((video.currentTime||0)/duration*100)+'%');seek.disabled=!loaded;}
 function ensureSource(){if(loadRequested)return;loadRequested=true;video.src=mobile.matches?'/assets/boutiquepilot-accueil-mobile.mp4':'/assets/boutiquepilot-accueil.mp4';video.preload='metadata';video.load();}
 async function play(){if(disposed)return;ensureSource();try{await video.play();}catch(e){if(!disposed&&e.name!=='AbortError'){wantsPlay=false;update();}}}
 function pause(){video.pause();update();}
 on(toggle,'click',()=>{if(video.paused){wantsPlay=true;play();}else{wantsPlay=false;pause();}});
 on(video,'loadedmetadata',()=>{loaded=true;update();});on(video,'loadeddata',()=>{figure.classList.add('film-ready');update();});on(video,'play',update);on(video,'pause',update);on(video,'timeupdate',update);on(video,'ended',update);
 on(seek,'input',()=>{if(loaded){video.currentTime=Number(seek.value);update();}});
 on(video,'error',()=>{if(disposed)return;wantsPlay=false;figure.classList.remove('film-ready');caption.textContent='Vidéo indisponible ici. Ouvrez l’aperçu en direct pour la lire.';label.textContent='Réessayer';symbol.textContent='▶';loadRequested=false;loaded=false;seek.disabled=true;});
 if('IntersectionObserver' in window){observer=new IntersectionObserver(entries=>{for(const e of entries){visible=e.isIntersecting&&e.intersectionRatio>=.20;if(visible&&wantsPlay&&!document.hidden)play();else pause();}},{threshold:[0,.20,.6]});observer.observe(frame);}else{visible=true;if(wantsPlay)play();}
 on(document,'visibilitychange',()=>{if(document.hidden)pause();else if(visible&&wantsPlay)play();});
 on(reduced,'change',e=>{if(e.matches){wantsPlay=false;pause();}});
 const trigger=document.querySelector('.hero-secondary');if(trigger){trigger.href='#home-brand-film';trigger.innerHTML='<span class="play-circle">▶</span>Découvrir en 20 secondes';trigger.setAttribute('aria-label','Voir la vidéo de présentation de Boutilo');on(trigger,'click',e=>{e.preventDefault();frame.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'center'});wantsPlay=true;play();toggle.focus({preventScroll:true});});}
 heroVideoDisposer=()=>{disposed=true;controller.abort();observer?.disconnect();video.pause();video.removeAttribute('src');video.load();};update();initHeadlineVideo();
}
